    summary: "李渊（566—635），字叔德，陇西成纪人，唐朝开国皇帝，庙号高祖，在位八年（618—626）。他出身北周八柱国之一的唐国公世家，与隋室姻亲相连，隋文帝独孤皇后是其亲姨母。隋末任太原留守，镇守北疆，广纳豪杰。大业十三年（617），他在次子李世民与晋阳令刘文静、晋阳宫监裴寂等力劝下，于晋阳起兵，当年十一月攻克长安，立代王杨侑为帝，自任大丞相、唐王。义宁二年（618）五月受隋禅称帝，国号唐，建元武德。武德年间，唐军先后削平薛举、李轨、刘武周、王世充、窦建德、萧铣、辅公祏等割据势力，基本统一全国。武德九年（626）六月玄武门之变后，李渊禅位于李世民，晚年以太上皇闲居，贞观九年（635）病逝，葬献陵。",
    background: "隋炀帝即位以来，营东都、开运河、修长城，又三征高句丽，连年征役，民力耗竭。大业七年（611），王薄在长白山首唱义歌，随后窦建德起于高鸡泊，翟让、李密据瓦岗，杜伏威转战江淮，天下大乱，群雄并起；而隋炀帝滞留江都，两京之间权力虚悬。李渊正出身于关陇贵族的最上层：其先祖李虎为西魏府兵八柱国之一，封唐国公，与北周、隋两代皇室世代联姻。李渊七岁袭爵唐国公，隋文帝独孤皇后是其亲姨母，故他虽居统治集团核心，却因「李氏当为天子」的图谶屡遭猜忌，不得不以纵酒纳贿自晦。大业十二年（616），隋炀帝以李渊为太原留守，备突厥、防刘武周。太原为北疆重镇，仓廪充实，李渊在此广纳豪杰，结交士族豪强。其次子李世民年方十八，胆识过人，与晋阳令刘文静、晋阳宫监裴寂密相结纳，力劝起兵；刘文静判断隋祚将终，劝其乘虚入关。李渊初虽犹豫，终定代隋自立的方略。",
