          "义宁二年（618）三月，宇文化及在江都发动兵变，缢杀隋炀帝。消息传至长安，李渊为之举哀。五月，隋恭帝杨侑下诏逊位，百官劝进，李渊三让而受，即皇帝位于太极殿，国号唐，建元武德，是为唐高祖。他追尊祖父李虎为景皇帝、父李昞为元皇帝，立李建成为皇太子，李世民为秦王、尚书令，李元吉为齐王；以裴寂为右仆射知政事，刘文静为纳言，萧瑀、窦威等分掌机密。新朝初立，百废待兴，李渊以安人静俗为务，罢郡置州，改太守为刺史，以州统县，简化层级；又下诏减免关中百姓一年租赋，释放宫女，分赐功臣田宅，务在收拢战乱离散的人心。",
          "武德间制度草创，多因隋旧而折中。土地与赋役行均田制与租庸调制：丁男授田百亩，永业二十亩可传子孙，口分八十亩还官；每丁岁输粟二斛，役二十日，不役则纳绢代庸，另输调绢二丈、绵三两。选官之途，一面恢复国子、太学、四门等学，一面于武德五年（622）重开科举，诏诸州岁贡明经、进士，寒门始有进身之阶。军事沿用府兵，关中置骠骑、车骑诸府，兵农合一，有事出征、无事归农。武德四年，废五铢钱，铸「开元通宝」，径八分，重二铢四絫，由给事中欧阳询题写钱文，轻重适中，通行天下。律令方面，命裴寂等损益隋律，武德七年颁新律，与令、格、式并行，刑网稍宽而法度粗具。",
