    interpretation: "李渊的历史地位，长期被贞观君臣的光环遮蔽。太宗朝修纂《高祖实录》以来，史笔多把他写成优柔寡断、被迫起兵的庸主，但细核史实并非如此。他以隋朝太原留守之身，在不到一年内完成起兵、入关、立代王、受禅四步，每一步都紧扣法统，把「代隋自立」的方略做得滴水不漏，足见政治老到。削平群雄之战，名义上的统帅是李世民、李孝恭，但战略次第、粮饷转输、人事调配皆出自长安，李渊居中调度之功不可埋没。他最大的失策，在于未能处理好太子与秦王的双头格局：既以建成为储君，又让世民之功赏无可赏，权力无法在两子之间均衡分配，终至喋血玄武门。武德朝的制度虽多因隋旧，却把均田、租庸调、科举、府兵与律令重新锻造成一套稳定的国家框架，为贞观之治铺好底子。可以说，李渊是唐朝这座大厦的奠基者，贞观的辉煌正是建立在武德八年打下的根基之上。",
