    interpretation: "玄宗一朝是唐朝由盛转衰的枢纽，也是帝制时代「人治」局限的典型样本。开元之治的成功，系于君主勤政与贤相秉政的配合：姚崇、宋璟、张九龄等以直言进谏为风，玄宗亦能受谏；而其转衰并非一朝一夕——开元二十四年（736）张九龄罢相后，李林甫为相十九年，杜言路、妒贤才，完成了相权专擅的制度化。玄宗以藩将安禄山兼三镇节度使，养兵十八万于范阳，使军事重心外重内轻；府兵制崩坏之后，中央无兵可调，渔阳鼙鼓一动，两京俱陷。马嵬兵变与其说是士卒哗变，不如说是朝廷积弊的总清算。玄宗前明后暗，非尽因杨妃之惑，实是长期承平消磨了政治警觉，而权力无约束则必然懈怠与用人失察。",
