    interpretation: "李白一生的悲剧，根源在其政治理想与身份、时代的错位。他自期「奋其智能，愿为辅弼」，却无科举出身，只能以词臣入翰林，本质是文学侍从而非治国之臣；玄宗赏其才华而不采其政见，高力士、杨贵妃之谗不过是加速剂。入永王幕，是他以布衣谋国的第二次尝试，却卷入肃宗与永王的皇室内争，几丧性命。从制度史看，他的人生折射出唐代士人上升通道的狭窄，以及盛世文人的政治天真。文学上，他将楚辞之奇想、庄子之逍遥、乐府之民歌活力与盛唐气象熔于一炉，把诗歌从宫廷台阁引向山河宇宙，完成唐诗由初唐雕饰向盛唐雄浑的转变。杜甫写实的深与李白浪漫的高，共同构成唐诗双峰，沾溉后世千年。",
