    interpretation: "杜甫之所以被称为「诗圣」，不仅因为艺术造诣，更因为他把个人命运与苍生疾苦、国家兴亡打成一片。他的诗被称为「诗史」，在于《三吏》《三别》《北征》《羌村三首》等以编年式笔法，记录至德、乾元年间战乱的具体场景与制度崩坏下的百姓处境，补正史之不及。在艺术上，他众体兼善，尤以律诗成就登峰造极，《秋兴八首》《登高》格律精严而气象阔大；《茅屋为秋风所破歌》将一己困顿推及天下寒士。中唐元稹作《唐故工部员外郎杜君墓系铭》，谓「诗人以来，未有如子美者」；宋以后经王安石、苏轼、黄庭坚等推崇，江西诗派奉为宗祖，诗圣地位遂定。存诗一千四百余首，影响中国诗歌千年。",
