    interpretation: "玄奘的意义，不止于一僧一寺、一经一论。从宗教史看，他以一人之力贯通中印，携归梵本六百余部，主持译出七十五部一千三百余卷，其「新译」与鸠摩罗什之「旧译」双峰并峙，使汉传佛教义学摆脱旧译歧互、疑伪杂陈的困境，法相、俱舍之学由此确立，并流播新罗、日本。从学术史看，《大唐西域记》以亲历者身份记录七世纪中亚、南亚一百三十八国的山川城邑、宗教政治，成为近代发掘那烂陀寺等遗址的依据，价值远出佛门之外。从政治史看，他以「私往」之僧，归国后反获太宗礼遇，受命译经著书，折射出唐初由边禁森严走向开放包容的转折；太宗、高宗两代借佛经、序文文治天下，亦见佛教与王朝政治的相互借力。而其孤身西行五万里、十七年不返的毅力，则使「宁可就西而死」的求真精神，超越宗教，成为中华文明史上一种象征性的人格力量。",
