    interpretation: "晋阳起兵之胜，首在战略方向。隋末群雄如李密、窦建德，皆逐鹿于中原四战之地；唯李渊父子定「乘虚入关，号令天下」之策，避实击虚，直取关中。关中沃野千里，据潼关、蒲津之险，进可制诸侯，退可保根本，实承秦、汉据关中制天下之故智。次在外交：卑辞结好始毕可汗，以金帛易战马、以和亲弭战端，稳固后方，免两线受敌。又在政治：始终以尊隋为名而行代隋之实，先立代王、后受禅让，使举兵有名，收隋室旧臣、关中士族之心；入长安即约法十二条、蠲除苛政，迅速安集百姓。然起兵首谋与百战之功多归李世民，而嫡长继承之制下定建成居储位，兄弟权势失衡，终启玄武门之变之端，此亦晋阳起兵埋下的一重远因。",
