    summary: "武德九年六月初四（公元626年7月2日），秦王李世民在长安太极宫北面的玄武门设伏，亲自射杀太子李建成、齐王李元吉，随即派尉迟敬德入宫宿卫，逼父唐高祖李渊交出大权。两日后，李世民被立为皇太子；同年八月初九，高祖传位，李世民即皇帝位，次年改元贞观。这场政变以骨肉相残的血腥代价完成了皇统更替，不仅一举终结了建国以来东宫与秦王府长达数年的明争暗斗，更直接开启了后世称颂的贞观之治，是理解唐代政治无法绕开的起点。",
    background: "隋末大乱中，李渊于晋阳起兵，次子李世民自十八岁随军，破薛仁杲、灭刘武周、擒窦建德、降王世充，为大唐统一天下立下首功。武德四年（621）平定洛阳后，高祖封他为天策上将、领司徒、陕东道大行台尚书令，位在王公之上；秦王府中文学馆十八学士与尉迟敬德、秦叔宝、程知节等骁将云集，势力之盛，连东宫也为之侧目。然而按宗法制度，储君只能是嫡长子李建成。统一战争结束后，居功至伟的秦王府与太子东宫水火不容：建成身为太子，名分早定；世民手握军功，人心所向。两方各自开府、广招僚属，朝中文武也渐渐分为两党。李建成联合李元吉，在后宫与朝中步步进逼：先以谗言遣散秦府旧臣，又将尉迟敬德等秦王府精锐调归元吉帐下，更借昆明池饯送之名，密伏壮士欲除世民。房玄龄、杜如晦被逐出秦府，长孙无忌等日夜力劝先发制人。李世民犹豫再三，终于定下政变之计。",
