        heading: "功高震主起争端",
        paragraphs: [
          "武德元年（618）大唐建国，李渊立长子李建成为太子、次子李世民为秦王、四子李元吉为齐王。按宗法制，储君之位早定；但天下未定，正是李世民大显身手之时。从晋阳起兵到攻克长安，从浅水原破薛仁杲到柏壁之战败刘武周、宋金刚，再至武德四年（621）虎牢关一战擒窦建德、降王世充，李世民率军转战数千里，为大唐打下大半江山。高祖特设天策上将一职授之，位列王公之上，兼领司徒、陕东道大行台尚书令，节制东方军政。洛阳平定后，他又开文学馆，收录杜如晦、房玄龄、虞世南、褚亮等十八学士，秦王府遂成文武并盛之府。",
          "李建成并非庸碌之辈。晋阳起兵时，他与世民同为统军大将；入关中、破长安，太子亦亲历行阵，立有战功。武德五年、六年，河北刘黑闼两度起兵，建成亲率大军征讨，魏征、王珪随军赞画，魏州、洺水之战颇有斩获，安定河北。但论军功之盛、收揽之广，远不及世民。东宫官属洗马魏征、中允王珪，屡屡劝建成早做准备。魏征曾进言：「秦王功盖天下，中外归心；殿下但以长年位居东宫，无大功以镇服海内。」劝他自请出征立功。然而军功可再立，名分不可改；两府的倾轧，渐渐从暗斗走向明争。",
          "到了武德七八年间，朝中文武渐渐各附一方。陈叔达、萧瑀、宇文士及等近臣倾向秦府；封德彝、裴矩等依违其间，暗中观望。后宫之中，高祖宠妃张婕妤、尹德妃与东宫交好，屡进谗言，说秦王自恃功高，不臣之心渐显。高祖李渊夹在嫡长子与功盖天下的次子之间，既不舍世民之军功，又不敢轻易废立，态度摇摆不定。他时而严词切责世民，时而又好言安抚。这种首鼠两端的态度，使两方都觉得最终只能依靠自己。分裂的种子，已埋在太极宫的砖石之下。"
        ]
