          "据《资治通鉴》记载，世民策马呼之，元吉张弓射世民，「再三不彀」，皆未射中；世民一箭射出，建成应弦而毙。尉迟敬德率骑兵赶到，射杀元吉。东宫翊卫车骑将军冯立闻变，率长林军数千人猛攻玄武门，秦府兵倚门拒战。张公谨独力闭合城门，挡住东宫人马。混战中，敬德持元吉首级示众，长林军遂溃。至此，建成、元吉双双伏诛，太极宫内外血迹未干，而李世民已控制宫城北门，掌握了全局。",
          "变起之际，高祖正与裴寂、萧瑀、陈叔达等重臣在海池泛舟。尉迟敬德擐甲持矛，直奔御前。高祖大惊，问：「今日作乱者是谁？卿来此何也？」敬德答：「秦王以太子、齐王作乱，举兵诛之，恐陛下惊动，遣臣来宿卫。」这番「宿卫」之名，实是软禁之实。高祖自知大势已去，只得问计于群臣。萧瑀、陈叔达劝高祖顺应时势，立世民为太子，委以国政。六月七日，高祖下诏，立世民为皇太子，「军国庶事，无大小悉委之」。"
