          "即位之后，太宗面对的是一个刚刚经历骨肉相残、人心惶惶的朝廷。他首先重用房玄龄、杜如晦为左右仆射，又擢魏征为谏议大夫，特许其出入卧内，以示坦诚。太宗曾问魏征：「人主何为而明，何为而暗？」魏征答：「兼听则明，偏信则暗。」从此广开言路，成为贞观一朝的政治底色。太宗还下令释放宫女三千余人，励精图治，与民休息；又平定突厥，擒颉利可汗。短短数年，大唐国势大振，四海归心。",
