    interpretation: "玄武门之变的深层逻辑，是开国军功体制与宗法继承制度的不可调和。唐初行府兵制，征讨子弟与秦王府结合，形成了一个以李世民为核心的军功集团；而东宫所代表的，是嫡长子继承制下的法统秩序。两者之间的冲突，不是简单的兄弟恩怨，而是「打天下的军功」与「坐天下的法统」如何衔接的结构性难题。李渊的处理方式是双头并重、两不相伤，结果是两头都不讨好：他既不能按制度立长而压制军功集团，又不能按功劳易储而动摇国本。犹豫摇摆之间，矛盾被推给了儿子们自己去解决。李世民选择先发制人，以暴力重新划定权力格局。从结果看，这一选择成就了贞观之治，太宗本人也以从谏如流的胸襟，尽力弥补政变留下的创伤。但玄武门之变也开了一个危险的先例：此后唐代皇位更替，几乎无不带血——神龙、唐隆、甘露之变，皆其遗响。它证明了一条铁律：皇权更替若不能制度化，便只能暴力化。",
