          "开元盛世鼎盛之际，危机已伏于制度之中。均田制崩坏，府兵失去土地依托，折冲府无兵可交，朝廷改行募兵，边镇兵额随之恶性膨胀：至天宝元年（742），十节度使所辖边兵合计达四十九万，而宿卫京师的彍骑不过十二万，外重内轻之势已成。安禄山以营州柳城杂胡出身，至天宝十载（751）身兼范阳、平卢、河东三镇节度使，拥兵十八万，尽握河北精锐。宰相李林甫倡以蕃将代汉将，对禄山百般姑息；杨国忠继任后与之争权交恶，屡言其必反。禄山遂以「忧国之危，奉密诏讨杨国忠」为名，于天宝十四载十一月起兵范阳。",
          "安史之乱的深层根源，在于唐朝兵制与政治结构的同时失衡。府兵制瓦解后，边镇军事集团以募兵维系，将卒久隶一镇，只知将帅不知朝廷，藩镇遂成独立于皇权之外的武力。李林甫以蕃将代汉将之议，本为防边将入相，却使安禄山一身兼制三镇、尽揽河北军政财权，尾大不掉。杨国忠继任后以私憾逼反强藩，玄宗以宠信蒙蔽视听，中枢既无制衡之策，亦无应变之备，乱事一起，遂致两京俱陷。就后果而言，战乱不仅造成人口流耗、中原残破，更使平叛以姑息了局——河朔三镇父子相袭，赋税自留，号令不入于朝廷，藩镇割据之局成为中晚唐政治常态；宦官典军与监军之制亦肇因于平叛，终成左右皇位废立之祸。此乱终结了开元盛世，也标志着中国中古时代由盛转衰的深刻转折，其制度教训，远在一时之成败之上。"
