          "然行卷既开，干谒请托之风随之而来，通榜、关节、势要嘱托之弊屡禁不止。举子竞趋权门，献卷争名，甚者造请权要、私通关节。长庆元年（821），钱徽知贡举，段文昌、李绅以所善之士请托不遂，讼于穆宗前，穆宗诏王起、李宗闵等复试，落第十人，钱徽贬江州刺史，科场案震动朝野，可见请托之盛。晚唐牛李党争数十年，牛党多进士出身，李党重门第经学，科第之辨竟成政争枢纽，此亦行卷干谒之风的政治回响。",
          "进士及第，仅得「出身」，尚须经吏部关试与铨选，方可释褐授官。关试由吏部考功员外郎主持，试判两道，合格者称「前进士」，再守选三年，赴吏部铨选，以身、言、书、判四事铨衡。登科之荣，冠绝一时：及第者集于慈恩寺大雁塔题名，谓之「雁塔题名」；曲江亭张宴，天子临幸，教坊奏乐，公卿随行择婿，长安为之倾动。孟郊年五十登科，喜赋「春风得意马蹄疾，一日看尽长安花」，其狂喜之情，千载如见。"
