    interpretation: "科举制的深层逻辑，在于选官权由门阀收归国家、由地方收归中央。以统一考试取代品评门第，使朝廷得以绕过世族，直接与天下士人建立授受关系——天子赐科名，士子报效朝廷，赵嘏「赚得英雄尽白头」之叹，正是此中消息。进士科尤以诗赋取人，文学才华成为进身阶梯，故《新唐书·选举志》称「大抵众科之目，进士尤为贵」。然科举亦是一柄双刃剑：它以功名羁縻士人，使才智之士皓首穷经、奔竞场屋；行卷干谒、通榜关节，又使科场难称绝对公平。至明清八股时代，代圣人立言渐成思想桎梏。然就制度史而言，科举以公开考试、择优录取为原则，打破血统门第，提供社会流动通道，实为古代世界最完备的文官选任制度，其影响远及东亚邻邦与近代西方文官考试。",
