    summary: "《大唐西域记》十二卷，唐贞观二十年（646）成书，是玄奘口述、弟子辩机执笔的西行见闻录。全书以行程为经、见闻为纬，记载玄奘亲历与传闻的一百三十八个国家与地区的山川、物产、政教、风俗，范围东起玉门、西抵波剌斯、南达僧伽罗。书中记那烂陀寺「僧徒数千，并俊才高学」，详阿耆尼、屈支诸国乐舞法制，为中原知识界打开了完整的天竺图景。此书不仅是唐代地理名著，更是研究中古中亚与南亚史的第一等原始文献，十九世纪经儒莲法译本西传，成为西方东方学倚为标准的典籍，并直接指导了那烂陀寺等遗址的考古发掘。",
    background: "贞观之初，玄奘以朝廷禁边、未蒙敕许，于贞观三年（629）冒禁出长安，西度玉门，历伊吾、高昌，越葱岭入五印度，前后十七年，行程五万余里。贞观十九年（645）正月，玄奘携梵本经论六百五十七部归抵长安，倾城出迎。二月，太宗适在洛阳，诏见于仪鸾殿，慰劳之余，详问西域诸国山川形势、风土物产、政教沿革，玄奘历述无遗。其时太宗经营西域，已平高昌、置安西都护府，正需详悉远方情状；又闻天竺佛化之盛、戒日王之强，锐欲知之，遂敕玄奘将西行见闻撰录成书。玄奘初以学浅辞逊，太宗不允，乃于弘福寺译经之暇，口述行历，命弟子辩机缀文记录，至贞观二十年（646）书成进呈。此即《大唐西域记》之由来。",
