          "贞观十九年（645）正月，玄奘自天竺归抵长安，倾城出迎。其时太宗已驾幸洛阳，将用兵辽东，闻玄奘至，即遣使迎劳，旋召赴行在。二月，玄奘入见于仪鸾殿，太宗慰劳甚至，问以去国十七年、历诸国几何。玄奘历述所经一百三十八国，自雪岭以西至于五印度，其山川形势、都邑关防、物产风俗、人物政教，随问条对，了如指掌。太宗大悦，以为自张骞、甘英以来，未闻有身至天竺、周览若此者，因命撰《西域记》一部，以备一代之典，又欲藉是以知西域诸国远近强弱、可以怀来宾服之状。玄奘初以学业未充、闻见不备辞，太宗弗许，撰事乃定。",
          "撰述之制，玄奘口述，弟子辩机执笔。辩机弱冠出家，博通经论，尤善缀文，玄奘遂选承旨记录之任。先是，玄奘归朝，即奉敕于长安弘福寺组织译场，翻译自天竺携归之梵本经论六百五十七部，昼夜无虚晷；《西域记》之撰，乃于译经之暇以口说授之，辩机秉笔，随事敷演，简练成文。玄奘记忆精审，虽在数万里外，城邑之广狭、寺塔之新旧、人物之年岁，忆之如昨日；其有传闻未详者，则明注「传闻」以别之，不敢妄下断语。故书成之后，记事赡博而体例严谨，非寻常摭拾地志之书可比。",
          "贞观二十年（646），书成，都十二卷，玄奘奉表进呈。其表自述西行之概，有「亲践者一百一十国，传闻者二十八国」之语，并谓所历山川皆图其形势，所闻风俗皆录其实然。太宗览毕，深加称赏，答书慰勉。此书虽承帝命而作，实成于玄奘亲践之真：张骞凿空，仅至西域；法显著《佛国记》，所记犹简；此书则自玉门以西，讫于波剌斯、僧伽罗，山川城郭、物产风俗、佛迹圣迹、王权兴替，粲然毕备，实为中原知识界第一部完整的天竺图景，亦千古纪行之巨制也。"
