    interpretation: "《大唐西域记》之成，固有太宗经营西域、欲悉远情之政略因素，然其所以能传世千载，端在「亲历」二字。玄奘以一介孤僧，十七年行五万里，所记一百一十国皆其目击，二十八国明注传闻，不掠虚美，不事臆测，其方法已近于近代之田野考察。较之法显《佛国记》之简略、前代正史西域传之辗转抄撮，此书以亲见亲闻正传闻之误，所关涉者不止佛迹，而于王权更迭、刑政税敛、物产商路、乐舞风俗，皆详著无遗，实为一部以宗教精神写成的中古世界地理志。唐人之胸襟视野，西域南海之山川人物，于此书可见其大；其兼为唐廷经略西域之向导、中古印度史之蓝本，一体而两面，斯其所以为不朽。",
