    interpretation: "甘露之变之败，其因有三：其一，宦官典神策军，握禁兵、据宫禁，天子欲除之，须先有密谋，而宫禁之中耳目四布，机事易泄；其二，文宗所用李训、郑注皆轻躁之士，欲以一朝之诈，成万世之功，伏兵单薄，举事轻率，韩约变色流汗，风动幕开，遂使大谋毁于一旦；其三，牛李二党交争于朝，文宗不信朝臣，故谋不出于宰相之府，而出于方术之门。事变之后，北司权势更张，南衙益弱，宦官拥兵立君，迄于唐亡而终不能制。故史家论唐之亡，以宦官之祸与藩镇之患并为根本，而甘露之变，正宦官之祸达于极点之标志也。",
