    interpretation: "淮西之役是观察中晚唐中央与藩镇关系之关键。安史之乱后，朝廷与藩镇维持平衡，淮西三州虽小，而居汴水漕运之冲，东南财赋所系，故朝廷必争；吴氏三世跋扈，朝廷姑息日久，至宪宗时国力稍振，始决意用兵。战事迁延三年，所暴露者非兵不利，乃统御之弊：十六道之兵，进止决于中使，将帅无专兵之权，故师老无功。裴度督师，奏罢监军，李愬乃得施其谋，可知制度理顺为用兵之前提。李愬收降纳叛，用敌将、乘敌隙，雪夜奔袭，看似行险，实基于李祐之情报与蔡州虚实，非侥幸而然。淮西平而淄青、成德归命，割据之局暂纾；然穆宗以后河朔复叛，中央威权复衰，可见军事之胜可收功于一役，而藩镇之弊根于政治经济结构，非一战所能尽除，元和中兴亦如回光之一瞬。",
