    interpretation: "会昌灭佛之祸，向来说者有二：一曰道佛之争，一曰财经之整肃。以史观之，道流进言、武宗好道，特其表象耳。安史乱后，两税法初行，税户仅三百八万，而军国所费十倍昔时，朝廷财用仰给无地；寺院占膏腴之田数千万顷，蓄奴婢十五万人，僧尼二十六万五百人不输课役，此皆国计之漏卮。李德裕以强干弱枝为务，武宗以绍祖崇道为名，君相相合，遂成此局。毁佛之入，佐泽潞之役、回鹘之征，会昌中兴，府库以充。然其效亦短：还俗之民归农无田，寺产入官旋即耗散；佛教赈灾济贫、维系乡里之能，一并毁弃。故自长远论，其得在于一时之财，其失在于经典散佚、宗派凋零——中国佛教自此由义学鼎盛，转向禅、净并行的山林格局。宣宗复佛，亦止于修复旧寺，终不能复义学之盛矣。",
