          "建中四年（783）十月，淮宁节度使李希烈围攻襄城，兵锋直逼东都洛阳。德宗情急之下，诏泾原节度使姚令言率本镇兵五千人东出救援。泾原军治泾州（今甘肃泾川），将士久戍西北边塞，九死一生，此番过关中，满望朝廷厚赏金帛以慰征戍之苦。不意德宗所遣犒军之使，进于浐水桥畔者仅粗粝饭食，肉帛俱无，京兆尹供应疏慢。军中哗然，咸谓辞父母妻子赴死于行阵，而朝廷待之如此，何以为战！积怨如烈火乾柴，一发不可收拾。",
          "乱兵遂裂旗鼓噪，持白刃折而西向，直趋京师。德宗闻变，急遣中使驰出慰抚，乱兵不奉诏，弯弓射之，中使奔还。俄而乱兵自通化门长驱入城，坊市无赖乘势聚从，沿途焚掠。德宗复命神策军使白志贞率禁军拒战，然神策军久居长安，多市井挂名避役之卒，一触即溃。姚令言自城外驰归，涕泣劝阻，乱兵不听，反拥之以行，令言遂从乱。宫门之外，已无朝廷之兵可战。",
