          "乱兵虽据京师，然群龙无首，自知不可以长久，乃议迎故帅为主。时故卢龙节度使朱泚罢职留京，居长安晋昌里。泚本幽州将，累功至节帅，建中元年入朝，留而不遣；其后弟朱滔叛于河北，泚遂不敢归，朝廷厚其禄而实防之。泾原将士多曾隶泚麾下，姚令言亦其旧将，乱兵乃趋晋昌里，罗拜迎泚入宫。泚既入禁中，出府库之财大赏乱兵，人心稍定，其势遂成，德宗所遣宣慰之使皆为所拒。",
          "是月，朱泚僭即皇帝位，国号大秦，建元应天（语见《新唐书·朱泚传》）。置百官，以姚令言、源休等分领机要，遣将四出，檄召诸镇。又大杀唐宗室之留长安者七十七人于崇仁坊，以绝人望，京师流血，士民股栗。泚发府库、散金帛以结群凶，又开仓廪以赈贫乏，欲收长安人心。由是关畿诸县望风降附者甚众，贼势大张。泚自以名应图谶，遂谋移唐祚，倾众攻奉天，欲一举擒天子以号令天下。",
          "前泾原节度使段秀实罢官留居京师，素以忠壮著闻，朱泚欲引为同僚以收人望。秀实阳为应承，阴结壮士刘海宾等，欲伺间诛贼。一日泚于朝堂议事，秀实勃然而起，夺象笏击泚，伤其面额，不中要害，为左右所害。秀实唾骂曰：狂贼！吾恨不斩汝万段，岂从汝反乎！朝野闻之痛惜。德宗在奉天闻之，赠太尉，谥曰忠烈，下诏褒其节义，以为人臣之表。"
