          "兴元元年（784）正月，德宗在奉天下罪己诏，陆贽秉笔，辞旨痛切，自述「天谴于上而朕不寤，人怨于下而朕不知」（语见《旧唐书·德宗本纪》）。诏改元兴元，大赦天下，凡李希烈、朱滔、田悦、王武俊、李纳等一切原宥，惟朱泚不赦；又罢间架税、除陌钱，与民休息。诏书颁行，四方感悦，王武俊、田悦、李纳皆去帝号谢罪，河朔戾气为之一夺，人心稍归于天子。",
