    interpretation: "泾原兵变表面起于一饭之薄，实则中晚唐中央与藩镇结构性矛盾之总爆发。德宗以两税法裕财，本欲以厚赏养兵、以神策军镇抚天下；然四镇连兵、李希烈继叛，军费浩繁，国库日虚，至以粗粝犒久戍边兵，恩义两绝，一激即溃。朱泚以失职之帅、闲居之臣，一旦乘乱僭号，而京畿州县望风降附，可见中央威信坠地，人心久已不属天子。德宗罪己改元、罢苛税以收人心，虽挽危局于既倒，然其志气已摧：削藩转为姑息，河朔终唐世不复为王者有；又以宦官典神策军，开中尉专权之局，其后废立由内，流毒至于唐亡。故论者谓，泾原一饭，非仅丧长安一日之主，实丧晚唐百年之势。",
