    interpretation: "马嵬驿之变历来被写成「红颜祸水」的道德故事，似乎杀了杨贵妃，开元盛世的政治积弊便可一笔勾销。此实为史家曲笔。杨玉环入宫十余年，未尝预政；真正乱政者，是玄宗本人——李林甫杜塞言路、杨国忠以聚敛进身、蕃将久任边镇，皆是玄宗怠政所授之权。兵变将士杀杨国忠，是泄其愤；缢死杨贵妃，是绝其疑。「贼本尚在」四字，道尽权力斗争的残酷逻辑：在溃败的皇权面前，天子宠妃不过是安抚军心的牺牲品。陈玄礼是否预通太子，正史语焉不详，《通鉴考异》亦存疑；然太子「未决」之态、变后径自分兵北上、灵武即位之速，皆可见其未必全无干系。此变更深长的意味在于：玄宗入蜀而失实权，肃宗以朔方军为根基重建朝廷，宦官李辅国以拥立之功渐掌禁军，中晚唐宦官专权、藩镇割据两大痼疾，皆种因于此时。故马嵬驿不只是一场宫闱悲剧，更是唐朝权力结构重组的起点。",
