    interpretation: "牛李党争之深层，实为两种取士之道、两类士大夫之争。牛党多为进士科出身，以文辞进身，长于论议；李党多出山东士族，以门荫入仕，重经术、礼法与实干。此本取人两途之轩轾，积渐而成门户之仇。科举既日重，进士新贵欲尽据清要；山东旧族犹以门第自矜，耻居其后，故郑覃请废进士科，李德裕亦屡抑词科之士。然两党相争，终无胜者，唯宦官坐收渔利：牛党先结枢密使杨承和，李德裕后亦倚北司，宰相进退系于宦官之口，皇权遂为北司所持。朋党互倾，则朝政反复，牛党得志则斥李党，李党秉政则贬牛党，贤才不获安位，国事随之凋敝。故史家论之，以为唐朝速亡之一因，与藩镇割据、宦官专权并为中晚唐三大痼疾。观文宗「去河北贼易，去朝廷朋党难」之叹，则知其患不在外而在内矣。",
