          "神龙元年正月二十二日癸卯（705年2月20日），武则天病甚，二张侍疾于迎仙宫，外臣隔绝。张柬之、崔玄暐联合敬晖、桓彦范、张仁愿、袁恕己等，说动右羽林卫大将军李多祚，率右羽林军五百余人自玄武门入，斩关而进。《旧唐书·卷六·则天皇后纪》载：「张柬之、崔玄暐、敬晖、桓彦范、张仁愿等率兵入玄武门，斩张易之、张昌宗于廊下。」二张不及防备，皆被斩于庑下，传首示众。又遣李多祚、王同皎、李湛至东宫，逼皇太子李显出宫面见武则天。王同皎抱太子登车，从至玄武门，左右簇拥而入。",
          "武士环立寝殿，刀光烛影，武则天惊起，问曰：「谁作乱？」桓彦范进前对曰：「张易之、昌宗谋反，臣等奉太子令诛之。」此载见于《资治通鉴·卷二百八·唐纪二十四》。太后见太子在侧，知事不可为，默然者久之。又见李湛在列，问曰：「汝亦为逆？」李湛乃李义府之子，对曰：「臣不逆，诛二贼耳。」事已至此，武则天遂令太子监国，是日皇太子总统万机，大赦天下，百官安堵如故。",
          "翌日，武则天下制传位于皇太子。二十五日丙午，中宗李显复即位，二月复国号为唐，百官、服色、旗帜悉复唐旧，武周一朝传十五载而终。中宗以张柬之、崔玄暐、敬晖、桓彦范、袁恕己功第一，皆封郡王：柬之汉阳郡王、玄暐博陵郡王、晖平阳郡王、彦范扶阳郡王、恕己南阳郡王，世称「五王」，各加特进。然五人封王之日即罢知政事，出之于外，朝政归于中宗、韦后与武三思之手。功高不赏而权去，祸机已伏于此。"
