    interpretation: "睢阳之战，实以一城之存废系天下之局。唐自丧乱以后，关中残破，平叛所资者，江淮之财赋也；江淮之能输关中者，汴河之漕路也；扼汴河之吭者，睢阳也。张巡以六千八百疲卒，牵制尹子奇十余万精锐十月之久，使贼既不能南犯江淮，又不能西援两京，唐军遂得以从容征兵回纥、整军反攻。城陷与洛阳克复仅隔数日，其牵制之大，可以想见。张巡守城，不专凭堞，辄出奇兵逆战，夜袭、设伏、草人绐箭，深得守中有攻之要，为后世城守之战所取法。至于杀妾飨军、城中至煮铠弩以拒贼，惨酷实所难免，后世颇有争议；然唐廷当时下诏褒赠立祠，李翰为撰《张巡传》辩之，正史具载其事，主流仍以忠烈殉国视之，历代配享武庙、从祀帝王庙，节义之光，炳然史册。",
