    interpretation: "此役为唐初国运转折之关键。太宗之胜，非独恃兵力，实乘敌之弊：颉利内政苛暴，部族离心，天灾人祸交乘，张公瑾所陈六条，已尽得其可击之状；唐廷则上下同心，励精图治，府库渐实，士卒精练，此消彼长，胜负之势判然。李靖用兵，深得疾雷不及掩耳之妙：三千轻骑深入虏庭，夜袭定襄；又违诏而战，乘使者在彼、敌备懈弛之际，直捣阴山牙帐，兵家所谓「将在外，君命有所不受」者也。太宗事后不罪其专，反加褒美，见知人之明。战后不诛颉利，而授官留养，处降众于河南，分置府州，以酋长世袭领之，遂开有唐一代羁縻蕃部之制。四夷共尊天可汗，唐乃兼为草原共主，北疆息警数十年，大唐声教远播，贞观盛世之基，实奠于此。",
