    interpretation: "唐隆政变之深远，须置于武则天以来的权力格局中观察。自武周革命、女主临朝，后宫、外戚与宗室遂成皇权争夺之主角：韦后效武后故事，安乐公主欲为皇太女，太平公主亦以拥立之功擅权。李隆基以宗王之身，结交北门万骑而得天下，可见自玄武门之变以来，禁军向背始终是皇位更迭之关键——唐太宗以此得位，张柬之以此复唐，李隆基又以此诛韦，禁军干政之传统，实为有唐一代皇位继承不稳的制度根源。此役另一层意义在于，它并未彻底铲除女主干政的土壤：太平公主以功臣之姿继起，权倾朝野，直至先天二年玄宗再行诛灭，方告终结。故唐隆政变可视为李唐宗室对武周以来女主政治清算的第一步，其结果不仅是睿宗复位，更是男系继承重归正统。自此以后，唐朝后宫不再有临朝称制之事，而宦官典军之弊渐萌，权力斗争由宫掖转向内廷与外朝之间。开元盛世之开，正以这两场政变扫清道路。",
