          "及至广德元年（763）七月，安史之乱甫平，史朝义首级传至京师未久，吐蕃已大举入大震关，陷兰、廓、河、鄯、洮、岷、秦、成、渭等州，河西、陇右之地尽没，蕃骑直叩关中。《资治通鉴·卷二二三》载：「吐蕃入大震关，陷兰、廓、河、鄯、洮、岷、秦、成、渭等州，河西、陇右之地尽没。」而唐廷之内，宦官程元振用事，构陷来瑱、排抑裴冕，权倾中外，边将告急文书皆为其压匿不奏，朝廷上下懵然，竟至兵临城下始知警耗，关中骚然，京师震骇，而备御已无及矣。"
