      {
        heading: "京师虽复，残局难振",
        paragraphs: [
          "然河西、陇右之地尽没，唐廷被迫遣使入蕃求和，默认失地。吐蕃既得陇右，岁岁东犯，游骑时至泾、渭，关中西门不启，代宗仅以朔方、邠宁诸军备御泾、陇一线，战守无虚日。永泰元年（765）九月，仆固怀恩以怨望结吐蕃、回纥、党项、吐谷浑数十万分三道入寇，行至鸣沙暴死，部众溃乱；郭子仪单骑说回纥于泾阳，回纥反戈共击吐蕃，蕃军大败，关中得全，然唐亦力竭，自此由外拓转入内守。",
          "河西走廊随之次第沦陷：广德二年（764）前后，凉州陷于吐蕃，甘、肃、瓜诸州相继而没，沙州军民苦守逾十年，至贞元二年（786）前后力屈而陷。安西、北庭与朝廷音问断绝，孤悬西域，约贞元七、八年间（791—792）先后没于吐蕃。河陇唐人陷于蕃境者，被迫辫发易服、沦为奴部，每岁秋获，蕃骑辄东掠，陇右沃野化为牧场，唐失养马之地，国势益蹙，西北边防自此全仗朔方、神策之军支拄。",
          "建中四年（783），唐蕃会盟于清水，唐正式承认吐蕃占有陇右，约以陇山为界，自此关中尽失河陇缓冲，长安长期暴露于吐蕃铁骑之下。唐廷内缩防线，倚神策军与朔方军镇守京西，外则结回纥、通南诏以牵制吐蕃，财赋尽仰江淮转输，民力困于水陆漕挽。吐蕃据长安虽仅十余日，然河陇尽没，帝国由外拓转入内守，与河北藩镇割据、宦官典军之患相纠缠，中晚唐之局，实定于此役。"
        ]
      }
