    interpretation: "此次长安之陷，表面上是边防空虚所致，实为安史之乱引发的系统性崩解。唐初以来以节度使重兵屯戍河陇、以攻为守的国防格局，因平叛内调而一朝瓦解；而中枢宦官程元振压匿边报，使朝廷丧失预警与调兵之机，暴露了宦官典军、将帅离心之痼疾。吐蕃虽以二十万众入关，然其性在掠夺人口财帛，而非城池治理，故立傀儡李承宏、伪署百官，仍行以华制华之策；据城十余日即西遁，说明其并无久据关中之力。长安虽复，河西陇右尽没，清水会盟以盟约形式确认失地，唐帝国失去养马之地与西陲屏障，国防线内缩，财政仰赖东南，外拓时代彻底终结。此后宦官典神策军、藩镇割据与吐蕃边患三者交织，成为中晚唐政治的三大痼疾。",
