    interpretation: "渭水之盟的本质，是实力悬殊之下以胆略与智谋弥补军力不足的危局外交。太宗即位未及一月，京畿空虚，若闭门死守则示弱于敌，若轻率出战则陷于众寡悬殊。囚执失思力以蔽敌耳目，六骑临阵以夺敌气，疑兵遍野以乱敌谋，间突利以离其党，四者环环相扣，皆攻心之术。颉利所以请和，非慑于唐军之众，实惑于唐军之不可测。此盟虽免倾覆之祸，然城下要盟，实为新君深耻。太宗此后偃革兴文、与民休息，复开互市以耗其力、册夷男以分其势，待国力既充而一举灭之，前后不过四年。其先和后战、以战定和之路径，与汉初白登之围后休养生息、终至汉武帝反击匈奴如出一辙，皆以隐忍为进取之阶。渭水之盟非妥协退让之终局，实为贞观之治与天可汗秩序之起点。",
