    interpretation: "文成公主入藏，是唐太宗边疆经略中「以婚代战」的一环。松州之役表明吐蕃已具与唐争锋的实力，太宗无意劳师远征青藏高原，遂以和亲换取西线安宁，此与汉世和亲有相通之处，而所携文化技艺之丰，又远过之。佛像、经籍、工匠与五谷同行，实为一次大规模的技术与文化输出：吐蕃的医药、历算、纺织、造纸因此得汉地之益，贵族子弟入国学读书，律令礼仪亦多取法唐制。舅甥名分一旦确立，唐蕃交往便有了制度化的通道，使者往来不绝，虽后来屡有兵争，长庆会盟仍以舅甥之义立碑盟誓。文成公主居藏近四十年，其遗泽非一城一地之得失，而在汉藏之间千年不断的文化往来。",
