          "用人不拘门第，是其治术明的一面。狄仁杰官至同凤阁鸾台平章事，为大周宰相，昔任大理丞时决滞狱一万七千人，无一诉冤者；后又荐引张柬之、桓彦范、敬晖、姚崇数十人，后皆朝廷柱石。姚崇在武周时已任夏官侍郎、同凤阁鸾台三品，后来辅佐玄宗开元年之治。武后亦能容直臣，徐有功、杜景佺持法平恕，屡遭诬奏而终获保全。她又留心农事，垂拱二年（686）亲撰《兆人本业》颁行天下，以为州县劝课农桑之法，田畴垦辟，户口渐增。",
          "治术暗的一面，是铜匦与诏狱。垂拱二年（686），于朝堂置铜匦四枚，分青、丹、白、黑四色，受四方密奏，以谏议大夫、补阙、拾遗充知匦使，告密之门由此大开。索元礼、周兴、来俊臣等酷吏以罗织发迹，撰《罗织经》以构陷无辜，酷刑逼供，宗室、贵戚、朝臣夷灭者数千家，朝士人人自危，宰相更换如走马。万岁通天以后，酷吏之害渐显于人主；神功元年（697）六月，来俊臣伏诛，周兴先流岭南死于道，索元礼亦诛，告密罗织之风始渐息，朝野方得喘息。"
