    interpretation: "武周革命是中国史上绝无仅有的一次女主代唐。其成功一半在制度，一半在权术：高宗遗诏「军国大事有不决者，兼听天后进止」给了她临朝的合法依据，铜匦与酷吏制造恐怖，佛教图谶与万民上表制造禅代的合法性。但以周代唐易，建立武氏皇统难：皇嗣李旦、庐陵王李显俱在，传位于子、还政李唐，几乎是宗法秩序下唯一的归宿。狄仁杰进言，以「姑侄与母子孰亲」点破此局，武后遂舍武承嗣、武三思而迎庐陵王回京。旧史家斥其篡逆，近世史家重其破格用人，两说并存。平心而论，酷吏之弊为开元所革，科举与用人之效为开元所承；十五年短祚，恰如一座桥，横在贞观与开元之间。",
