    interpretation: "玄奘西行，表面是求法，实则以一人之力贯通七世纪亚洲的精神版图。其未经文牒出境，本属违法，然归国之日，太宗不究擅行之罪，反迎劳备至，可见大唐法度虽严而襟怀足以容非常之举。所携六百五十七部梵本，主持译出七十五部一千三百三十五卷，译笔之精审远迈前古；所传法相唯识一宗，使印度瑜伽行派真传入华。更可珍者乃《大唐西域记》十二卷：以亲历亲闻录下中亚、南亚一百三十八国之山川城郭、物产风俗、宗教盛衰，印度那烂陀寺遗址之发掘、戒日王时代之考订，多赖此书为证。十七年五万里，是宗教苦行，也是文明丈量；其所成就，已远超一宗一派之范围，而成为中华文明向外求索、又反哺世界的一段象征。",
