    interpretation: "元和中兴之成，在于宪宗以英锐之主，乘江淮财赋之利，佐以杜黄裳、武元衡、裴度等谋国之臣，对藩镇剿抚互用：先取西川、镇海立威，再收魏博以孤河朔之势，终以淮西一战震慑天下，淄青、成德望风而服。其用兵之费，多出德宗内库积蓄与江淮两税，故能支淮西三载之鏖战。然其失亦在此：兵威虽盛，制度未改，节度使拥兵自署之制如故，河朔三镇不过畏威而服，非心服也；宦官典神策军、典监军之弊，不但未除，反因用兵而益深，终致宪宗身死于宦官之手。故元和中兴乃皇权对藩镇的一次强力反弹，而非结构性的复兴。宪宗遇弑后，穆宗君臣不知守成，长庆元年河朔尽失，其后牛李党争、甘露之变相继，唐祚遂不可复振。",
