          "朱温篡唐，并非一朝一代之更替，而是整个政治结构的翻转。他以宣武镇的将帅班底建立朝廷，节度使出镇四方、权兼中央，方镇体制被原封不动搬进帝国之中。宫中无宦官可恃，禁军皆出身藩镇旧部，皇权反而受武将拥立之制衡。朱温又以开封为都城，政治中心自此由关中东移至运河之畔，长安数百年的帝王之业宣告终结。他奖励农桑、减免赋役，中原经济得以稍苏；然其猜忌好杀、纵兵劫掠，后梁国势始终未能安稳。",
          "以兵权夺天下者，终亦受制于兵权。乾化二年（912），朱温因立储之争，被次子朱友珪联合禁军将佐杀死于洛阳，终年六十一岁。后梁宗室内乱相仍，龙德三年（923），后梁末帝朱友贞在河东李存勖的进攻下身死国灭，立国仅十七年。自朱温篡唐至赵宋立国，五十三年间中原历经梁、唐、晋、汉、周五朝，南方则十国并立，诚如欧阳修在《新五代史》中所叹「五代之乱极矣」，而其开端，正是朱温以藩镇武将身份完成的这场篡夺。"
