    interpretation: "朱温篡唐并非一人一朝之变，而是安史之乱后一百五十余年藩镇割据逻辑的最终收束。唐朝皇权赖以维系的三根支柱——神策军、宦官集团与关中财赋——在黄巢之乱中崩塌殆尽，朱温则以最彻底的方式完成最后一击：他既诛尽宦官第五可范等数百人，又屠裴枢等朝臣三十余人于白马驿，实际上同时剪除了皇权的军事护卫与文官体系，使天子彻底成为武人手中的空名。他本人的出身更耐人寻味：起于黄巢流民军，受唐朝官爵与赐名，再以唐朝节度使身份篡唐，正可见乱世之中兵强马壮者自为帝王的残酷法则。五代十国的政权更替几乎都沿袭这一模式：兵权即政权。与此同时，朱温定都开封，政治中心自此东移，关中帝王之业告终；白马驿之祸中「清流」投于浊流，象征着自魏晋以来门阀士族在政治上的彻底消亡，中国政治自此转入武人专政时代，直至赵宋立国才以文制武、重归秩序。",
