    interpretation: "安禄山之乱，非一人之叛，乃制度之变。其根本，在开元、天宝间兵制与边防格局之重构：府兵既坏，募兵代兴，诸道节度使兵财自专，朝廷无内兵可制；蕃将专镇之策本为防边将结党入相，反使禄山兼三镇之重，聚河北精兵于一身。玄宗以私恩代国法，铁券、郡王、母子之戏，皆以帝王之尊自堕纲纪；李林甫固宠于前，杨国忠激变于后，宰相相倾而祸发。故史论以为，禄山能乱唐，实唐自乱也。其影响深远：两京残破，户口耗减，天子威信扫地；朝廷以宦官典禁军、以藩镇制藩镇，河北三镇名为臣服而实自署官吏，赋税不入版籍，终唐之世不能去。大唐由盛转衰，藩镇割据之局由此而成，五代十国之分裂，亦肇端于此。",
