    interpretation: "白居易的深层意义，在于他把诗歌从庙堂雅玩变成社会批评的工具。新乐府运动上承《诗经》美刺传统，以《卖炭翁》写宫市、《重赋》写税法、《轻肥》刺宦官，使诗歌第一次系统地介入现实政治。但他的政治理想最终让位于现实：武元衡案中的贬谪、河北用兵的受挫、牛李党争的倾轧，使他由「兼济天下」走向「独善其身」，以分司东都的方式自全——这不是消极，而是中唐士人在宦官与党争夹缝中的典型生存策略。他的诗歌因此兼具讽喻、感伤、闲适三面。其影响远及海外，《旧唐书》载新罗宰相以百金购其诗一篇；平安时代的日本，白居易诗几乎人手一编。他既是伟大的诗人，也是理解中唐社会的一把钥匙。",
