    interpretation: "杜如晦的相业，须置于唐初由武功向文治的转变中理解。隋末大乱之后，天下初定，朝廷面临的核心问题不是打天下，而是如何定制度、理政事、息争讼。杜如晦以秦府旧臣而位至右仆射，其真正贡献不在谋一事、决一狱，而在与房玄龄共同搭建了尚书省运行与律令修撰的框架，使贞观政风有法式可循。「房谋杜断」之说，道出宰相搭配的理想形态：谋贵周密，断贵明决，二者缺一，则议而不行、行而不当。他贞观四年早逝，未能亲见贞观之治的全盛，故两《唐书》本传所载政绩多与房玄龄并称，个人行事反少；然凌烟阁二十四功臣位列第三，尚在魏征、房玄龄之前，足见其佐命定策之功在太宗心目中的分量。",
