    interpretation: "房玄龄的一生，折射出唐初政治由武功向文治的转轨。他出自山东士族，以文学进身，却投笔从戎，将文吏之才注入军事集团；入唐以后，又以律令、史书塑造国家规范，使马上得来的天下复归于治。这是贞观之治得以成立的深层逻辑：以秦府旧人为腹心，以律令格式为纲纪，以史鉴为镜。玄龄善谋而不自专，闻人有善若己有之，故能总百司、集群才。然其晚年亦见盛极之危：子房遗爱尚高阳公主，永徽四年（653年）以谋反被诛，玄龄配享太庙因之中绝，裔嗣衰替。然《贞观律》为唐律之基，流衍为《唐律疏议》，影响及于东亚；《晋书》一百三十卷列于正史，体例载记并存。其人虽逝，其制度文章传之久远，故后世论贞观良相，必曰房、杜。",
