          "高宗朝，府兵武功达于极盛。显庆二年（657年），右屯卫将军苏定方率府兵出金山，追击西突厥沙钵罗可汗阿史那贺鲁，战于曳咥河、金牙山，直抵石国，生擒贺鲁，西突厥灭亡，唐之势力西抵咸海。苏定方所率，多为陇右、关中折冲府兵，转战数千里，粮械自随，乃府兵机动作战之巅峰。此后显庆五年（660年）苏定方平百济；总章元年（668年）李世勣、薛仁贵拔平壤，灭高句丽。唐疆东至大海，西达葱岭，北抵大漠，皆府兵将士刀剑弓马所辟。",
