          "开元十一年（723年），宰相张说建策，募士宿卫，号「长从宿卫」，后称彉骑，募兵渐代府兵。彉骑免其征镇赋役，由国家供给，宿卫京师。开元二十五年（737年），边镇戍卒亦改行招募，长征健儿长镇边隅，许携家口，官给田宅粮赐。自此宿卫、戍边皆出于招募，府兵徒存空名。张说以彉骑省逃亡之弊，然兵既招募，则人习于久戍，将得专其部伍，天子之兵渐变为边将之兵。",
