    interpretation: "府兵制的核心在于「兵役与土地相结合」。国家授农民以田，农民报国家以兵役，军费主要转嫁于农民家庭，国库不费巨帑而常养六十万兵。其统御之精，在于折冲府掌兵籍、十二卫统宿卫、皇帝持调发之权的分离，将不专兵、兵不属将，消除南北朝将帅擅权之祸。故贞观至开元，唐军能征四夷、拓土万里，而朝廷无武将割据之忧。然府兵以均田为根基，田制坏则兵制崩：农民失田逃亡，兵役反成重负，自备粮械无力承担，兵源枯竭，势所必然。张说改募兵，虽解一时之急，却使兵将相隶、边将专兵，终启安史之乱与藩镇割据。府兵兴废证明，兵制之根本不在兵法，而在田制与财政。",
