    interpretation: "李林甫之专权，非一人之奸，乃制度之弊与君心之怠相合而成。玄宗开元初，姚崇、宋璟以直道辅政，张说、张九龄犹守经术；及盛世既成，帝志满而倦万机，欲得顺旨之臣，林甫乃以「言辄合旨」进。中书门下并政事堂之权于一署，宰相兼典铨选、台谏，则进退百官、钳制言路皆出一门，此权臣窃柄之制度本源。其弊有二：一则蔽塞言路，立仗马之喻一出，谏官噤口，杜璡贬而朝无直声，杜甫落选而野无遗贤，朝廷耳目尽失；二则胡将之议，断边将入相之阶，又值府兵坏、募兵兴，节度使久任拥兵，安禄山遂并三镇，兵十八万，乃成不可悔之势。故身死未几，剖棺改葬，而乱兵已起范阳。论玄宗朝由盛转衰，多以其为枢纽，以其逢君之欲、坏制之防、养边之祸，三者皆不可救也。",
