    interpretation: "李光弼之一生，实为唐室两大痼疾之缩影。其一为蕃将任用之制。自开元以降，府兵崩坏，募兵代兴，边防全委蕃将，安禄山遂以三镇之众倾覆天下；而平定其乱者，郭子仪、李光弼亦皆朔方、河东之镇将——以方镇御方镇，虽收一时之功，终启百年藩镇之祸。其二为宦官监军之弊。肃、代之世，鱼朝恩、程元振以观军容使、判元帅府行军司马之权，掣肘于上。邙山之败、吐蕃之危，皆与之相系；李光弼功高不赏，拥兵自疑，忧死徐州，而神策军权自此尽归内廷。其用兵谋定而后战，能以少覆众，出井陉、守太原、战河阳，堪称唐代第一流将略；然将帅之祸福，竟系于宦竖之恩怨，则大唐国势之由盛转衰，已于其一身见之矣。",
