    interpretation: "柳宗元的一生，是中唐政局的一个缩影。永贞革新之败，非尽人事，亦时势使然：顺宗中风失音，政出多门，宦官典禁军而藩镇连衡，革新派以书生骤掌大权，欲以百日之政芟除百年之弊，其势如以卵击石。后世对革新评价不一，或病其躁进，或矜其忠鲛，然罢宫市、禁五坊、抑宦官诸举切中时弊，主流仍予肯定。柳宗元的悲剧在于政治生命终止于三十三岁，而文学与思想生命恰恰由此开启：永州十年，谪居之苦反成其文之大幸，正所谓「国家不幸诗家幸」。其《封建论》论郡县之利，《天说》破感应之迷，为中唐思想界之峻论；柳州释奴，以工抵债，实为古代奴婢制度中难得的人道实践。至于韩柳并称、唐宋八大家之列，其文章地位已非政途得失所能限。",
