          "论其影响，首在文献汇聚。唐宋以来，唐诗总集若《唐诗品汇》《唐诗归》之类，皆选本也；胡震亨、季振宜二书虽称全辑，终未广布通行。《全唐诗》以官修之力，九百卷巨帙镂板颁行，使李杜元白、王孟高岑之作汇聚一堂，学者安坐而可尽览唐音，唐诗研究始有根本之渊海。清人沈德潜编选《唐诗别裁集》，亦多取资于是书；乃至今日之唐诗选本、辞典、数据库，溯其源流，鲜有不资于此者。",
