    interpretation: "《全唐诗》之修，非仅文献汇辑，实为清廷文化统绪建构之一环。圣祖以满洲入主中原，亟须宣示承续华夏道统：开博学鸿词以收揽遗民，敕修群书以彰显右文，修唐诗总集亦同一机杼——以总结汉族文学之巅峰，确立新朝之文化正统。就编纂本身而论，期年而成近千卷巨帙，速则速矣，然底本既限二书，见闻复囿于时代，遗珠误收在所不免，速成与精校本难两全。其功则在于：以官修之力，集十翰林之才，使散见于千余部别集、总集、地志、笔记中之唐人歌咏，汇为定本。此后有《全唐诗补编》之补苴，有中华书局点校本之普及，唐诗之全貌遂日益清晰。要之，一代文学之总汇，成于异代帝王之手，此亦文化传承之奇观。",
