    summary: "宋璟（663—737），邢州南和（今河北邢台）人，唐代名相，后封广平郡公，世称宋广平。少耿介有大节，好学工文，进士及第。历仕武周、中宗、睿宗、玄宗四朝。武后末年张易之、张昌宗弄权，璟独面折之，直声震朝野。开元四年（716）继姚崇为相，守刑部尚书、同中书门下平章事。为相轻赋税、省刑罚、抑侥幸、绝私请，犯颜直谏，不避权幸。开元八年（720）因禁断恶钱连坐罢相，后拜尚书右丞相，致仕东都。开元二十五年（737）卒，年七十五，赠太尉，谥文贞。与姚崇并称「姚宋」，合房玄龄、杜如晦为唐代四大贤相，为开元盛世的重要奠基者。",
    background: "武则天晚年，张易之、张昌宗兄弟以宠幸乱政，朝臣多附之。神龙元年（705）张柬之等诛二张、扶中宗复位，韦后与武三思复窃威柄，朝局翻覆。中宗怯懦，韦后干政，武三思居中用事，张柬之等五王相继贬死，墨敕斜封之官动以千数，纪纲大坏。景云元年（710）睿宗即位，太平公主权倾天下，太子李隆基与之角立。先天二年（713）玄宗先发诛太平公主党，皇权始安。迭经数变，百官习于依附，法纪久弛。玄宗欲致太平，开元元年（713）起用姚崇，以十事为说，整顿纲纪。姚崇长于权变，因事制宜，数年间粗见成效。开元四年（716）姚崇罢相，然恩幸干进、食封冗滥、钱法紊乱诸端犹在。天下初定之后，所须已非奇谋权变，而是持正守法、裁抑侥幸之宰臣，宋璟遂以刑部尚书、同中书门下平章事继秉国钧。姚崇善应变，宋璟善守法，恰为开元之治一体之两面。",
