          "景云二年（711），太平公主权倾天下，朝中宰相七人，五出其门，太子李隆基深以为忧。宋璟与姚崇密奏睿宗，请出太平公主于东都洛阳，并出岐王李范、薛王李业为外州刺史，以安太子、保全宗庙。事未行而泄，太平公主泣诉于睿宗，睿宗不能用其言，乃并罢姚崇、宋璟知政事：姚崇出为申州刺史，宋璟出为楚州刺史。其后宋璟历兖、冀、魏三州刺史，所至以清严称。",
