          "宋璟以贞观故事为法度，奏请恢复太宗朝旧制，许谏官、御史随宰相入阁议事，凡政事得失，得面陈论难，于是言路重开，朝风为之一变，奸佞稍知敛迹。又以刑罚久弛，奏请省减烦法、矜恤疑狱；以食封之家冗滥，奏请量加裁损封户，国家岁入渐有节度。其为政务在清简约，不欲烦扰百姓，所司各率其职，数年之间，纲纪渐张，恩幸敛迹，朝廷气象为之肃然。",
