    interpretation: "开元之治，前有姚崇以权变济之，后有宋璟以守法成之。自武周末年至先天之间，宫廷迭变，朝臣习于趋避，政治风气以依附权势为务。宋璟以面折二张始，以守法持正终，一生行事皆在一「正」字。其见重于玄宗，不在谋略奇功，而在以个人风节重立百官对法度的敬畏：谏官、御史复得随宰相议事，言路因之渐开；铨选、刑狱皆循令式，侥幸因之稍衰。然其罢相一事，亦见开元政事的另一面——制度之立，赖执行之实。禁断恶钱，立法本为救弊，而强括于江淮，市井不通，民怨沸腾，宰相遂以此连坐去位，可见政令不可专恃禁断，须恤其施行之害。宋璟罢后，张嘉贞、张说、李元纮、杜暹相继秉钧，开元之盛已成，而直臣之风渐替；天宝以后，李林甫、杨国忠专事迎合，法度陵夷，终致安史之乱。宋璟在相位不过四年，与姚崇并称「姚宋」，合房玄龄、杜如晦为唐代四大贤相，其守法持正之政，实为开元盛世由权变走向常轨的关键一环。",
