    interpretation: "颜真卿一生，与唐王朝由盛转衰相终始。天宝盛世之下，李林甫、杨国忠相继擅权，正士远迹，朝政渐坏，安禄山遂以边将坐大，一朝反叛，河北二十四郡几无完者。唯平原独举义旗，十七郡响应，真卿以一书生守郡，为唐廷重集平叛兵力赢得时机，此非仅一人之忠勇，亦见节度使制度崩坏之际，地方守臣犹存人心。入朝之后，历仕肃宗、代宗、德宗，以刚直忤四任权相，屡遭贬黜，终以七十六岁高龄使贼蔡州，全节而终。其书法变初唐瘦硬为浑厚雄壮，开创颜体，与柳公权并称「颜筋柳骨」。书风之变，实与世运相应：盛世姿媚，乱世雄浑。颜真卿以忠义立身，以笔墨传世，二者合而为一，故千年之后，观其碑帖者犹想见其人。唐室虽衰，而颜体与颜公之名，历久弥新。",
