          "杨国忠本名杨钊，蒲州永乐（今山西永济）人，《旧唐书》本传开篇即书「国忠本名钊，蒲州永乐人也」。其家世本非寒微：则天朝幸臣张易之即其舅父，神龙元年（705）张柬之等诛二张，张易之伏诛，杨氏一支遂零落。杨钊少时不事生产，嗜酒好赌，无行检，为宗党所轻。后发愤从军，客游蜀中十余载，仅授新都尉。任满待选，家居成都，贫不能自存，日从恶少饮博，蜀中豪商多掩鼻避之。唯富豪鲜于仲通以为此人仪表非常，厚待之，为日后起家埋下伏笔。",
          "天宝四载（745）八月，玄宗册寿王妃杨氏为贵妃，恩宠冠绝后宫。杨氏一门骤贵：长姊封韩国夫人，三姊封虢国夫人，八姊封秦国夫人，出入宫掖，势倾朝野。时剑南节度使章仇兼琼恐朝中无援，欲结贵妃为内援，闻杨钊为贵妃从祖兄，乃厚遗金宝，遣之入京。杨钊至长安，授金吾兵曹参军，得供奉禁中。贵妃三姊虢国夫人新寡，杨钊与之私通，由是得出入宫掖，得觐玄宗。天宝五载（746），杨钊以内戚兼中帝意，始预朝政，朝廷百官见其宠遇日盛，争相趋附。",
          "杨钊仪观甚伟，口辩给，善窥帝意。玄宗晚年好货，钊善计算，钱谷簿书过目能究其本末，奏报悉中帝意。初入禁中，尝为帝樗蒲筹算，锱铢不爽，帝以为能。天宝七载（748）擢度支员外郎，兼侍御史，始掌财计。岁入大增，左藏、大盈库充盈，帝以为能，故不次超擢。玄宗曾引百官观左藏，赐帛有差，赏其聚敛之功。由度支郎中而至卿监，不过数年，朝野侧目。其骤兴之源，实在玄宗暮年怠政、宠任外戚与聚敛之臣。"
