    interpretation: "姚崇一生，凡三度为相而三落三起，其所以能拨乱世而反之正者，在于一「变」字。司马光论曰「崇善应变，璟善守法」，一语道破姚宋之别。武周末年至开元初，唐室之弊凡五：酷法、冗官、戚宦干政、佛道滥费、边功耗财，皆数十年女后外戚专权所积。崇以《十事要说》为纲领，条条对症，非空谈王道者可比。其焚蝗之议，尤见卓识：举朝视蝗为天谴，束手待毙，独崇以人事抗天命，谓纵不能尽除，犹胜养患成灾。此种务实精神，实开开元富强之风。然崇非完人：不能约束子弟，坐受馈遗之累，终以赵诲案罢相，故其荐宋璟以守法自代，实有自知之明。开元之治，姚崇以变局开其端，宋璟以法度守其成，张说、张九龄继之，遂成盛世。论者谓有唐贤相，前称房、杜，后称姚、宋，而开元一代规模，实自姚崇手创。",
