    interpretation: "《艺文类聚》的深层意义，须置于唐初政治文化格局中观察。武德五年下诏、七年成书，仅用两年，足见新朝动员之高效。高祖李渊以军功立国，却急于修纂一部供省览抄撮之类书，其意不止于临文，更在以文化建设宣示正统、收拢隋末离乱中的南北士人。修书班底中，欧阳询出身岭南、陈叔达为陈朝宗室、令狐德棻为关陇士人，正是南北合流的缩影。「事文合编」看似体例小变，实则解决了类书偏废之弊，使知识检索与文学采摭合而为一，奠定宋明类书基本格局。而其最大之功，在保存文献：所引一千四百余种古籍，十之八九今已散佚，魏晋南北朝大量诗文赖此书得以保存。书成于武德七年，两年后即玄武门之变；高祖朝的文治设想，最终由贞观君臣赓续发扬。要之，此书既是唐初大一统文化整合的产物，也是后世辑佚校勘先唐文献最重要的渊薮。",
