          "贞观二十三年五月，太宗病笃于翠微宫，遗诏以无忌与中书令褚遂良同辅高宗。太宗尝谓高宗：「无忌、遂良在，汝勿忧天下。」高宗即位，进无忌太尉，检校中书令，知门下、尚书二省，总揽朝政。永徽初，无忌以元舅之尊，裁决万机，天下大政，多出其门。史谓「无忌贵戚好学，该博文史，性通悟，有筹略」，观其当国，进贤退不肖，永徽之政，颇有贞观遗风，良非偶然。其受遗托孤，同汉之霍光，而权位之重，有过之无不及。",
          "永徽二年，无忌以律文疑滞、吏议纷错，奏请修疏，以一断狱之准。永徽四年，主持修成《唐律疏议》三十卷，颁行天下。其书因隋《开皇律》之旧，析为名例、卫禁、职制、户婚、厩库、擅兴、贼盗、斗讼、诈伪、杂律、捕亡、断狱十二篇，律文五百条，逐条疏解，引经断义，集前代立法之大成。疏与律合，法官断狱，皆引疏析之，自唐历宋，相沿不废；东传日本、新罗，皆为轨范，中华法系之圭臬，于斯为盛。"
