          "自永徽五年起，高宗欲废王皇后、立武昭仪为后，无忌以王后名门正位，无显过，坚决反对。高宗密赐无忌金银宝器锦帛，欲动其意，无忌屡拒之。永徽六年，高宗召无忌、于志宁、褚遂良议之，李绩独称疾不至，遂良死谏，无忌持正不回。许敬宗扬言：「田舍翁多收十斛麦，尚欲易妻；况天子欲立一后，何豫诸人事而妄生异议乎！」高宗意遂决，废王氏，立武氏为后，无忌自此见疏，武后深衔之。",
          "显庆四年四月，洛阳人李奉节告太子洗马韦季方、监察御史李巢朋党，诏许敬宗与侍中辛茂将鞫之。敬宗素附武后，欲借此构陷无忌，逼季方引无忌同谋，季方不承，敬宗乃诬奏无忌谋反。高宗惊泣，不欲加罪，敬宗以汉文帝杀舅薄昭为言，迫帝就范。诏削无忌太尉、赵国公，流黔州。七月，许敬宗、李义府遣大理正袁公瑜至黔州，逼令自缢，籍没其家，子弟侄甥皆流岭南。一代元勋，死于非命。",
          "无忌既死，武后之患始解，朝中关陇旧臣剪除殆尽。上元元年，追复无忌太尉、赵国公官爵，陪葬昭陵，还其产业。作为关陇集团最后一位权臣，无忌的浮沉，折射出贞观至永徽年间皇权、外戚、功臣三股势力的消长。其以布衣之交佐命开国，以元舅之尊托孤当国，终以谏争废立，宗社倾覆，身死家没。然《唐律疏议》三十卷，垂范千载，凌烟阁画像，长为后世所瞻，其功自不可没也。"
