    interpretation: "长孙无忌之一生，实为初唐政治结构变迁之缩影。其崛起，赖于关陇集团之煊赫与太宗布衣姻旧之信任；其秉政，则是皇权与功臣外戚共治格局的极致形态。贞观之治，名在太宗，而成于无忌、房玄龄、杜如晦辈之辅翼，此辈或出关陇，或出山东士族，政治与社会基础深厚。永徽之政，号称有贞观遗风，实为无忌以顾命元舅总揽万机之产物。然高宗非幼弱之主，武后更有雄猜之才，帝后欲伸皇权，必先去元舅。废王立武之争，表面为宫闱之事，实为皇权、外戚、功臣三股势力之决战。无忌败，则关陇集团百年基业摧陷廓清，科举新进之臣如许敬宗、李义府辈乘势而起，朝局为之一变。故无忌之死，非一人之悲剧，乃一个时代之终结。其所修《唐律疏议》，不因人亡而废，反垂范千载，东被日本、新罗，为中华法系之骨干，此则武功政治之外，更深远之遗产也。",
