    interpretation: "租庸调的本质，是国家和编户之间一场以土地为中介的交换：国家授田百亩于丁男，丁男则以租调庸回报。它的精妙处在「庸」——以绢三尺折一日之役，使农民不离田亩、不废农时，国家亦得实入；隋开皇十年「不役者收庸」已开其端，唐则推为常制。此制能支撑贞观、开元百余年，不在税则本身，而在均田未坏、户籍未乱；安史之乱不过是压垮它的最后一击，在此之前，逃户、兼并、隐漏已使田与丁脱钩数十年。故宇文融括户所得八十余万客户、天宝十一载的抑兼并诏，都是制度自救失败的记录。建中元年两税法以贫富为差，实是承认国家已无力授田计丁，只能改向田产征税。自此之后，中国赋役史从「以人丁为本」走向「以资产为宗」，力役渐以实物、货币代偿，迄于明代一条鞭法与清代摊丁入亩，这条线索始终未断。",
