    interpretation: "代宗之世，唐室最要紧之局，可一言以蔽之：平乱而不能复驭。乱虽平，而致乱之由未除：府兵既坏，募兵归于藩镇；节度使之权重，本为御边而设，至河朔三镇而变为世袭之私物。代宗以田承嗣等降将就地授节钺，非尽出于姑息，实因国用凋敝、吐蕃逼蹙，无余力再举河北之师，两害相权取其轻；然割据之局由此坐大，终唐之世未能荡平。典军之权既归于宦官，虽有刺李辅国、流程元振、诛鱼朝恩之举，而去其人不能去其制，神策军权仍为内廷所握，宦官专权之祸遂与唐相始终。财政上，刘晏通漕、榷盐，实乱世聚敛与养民并济之法，国用赖以不匮，然专使权重，又开此后财政体系外重于宰相之局。代宗以权术驭乱世，可谓应变之才，而终未能为唐室立长治久安之法，此其限也。",
