    interpretation: "德宗一朝，是唐朝由乱求治、再转因循的转折点。其一生毁誉，系于两件制度遗产：两税法与神策军中尉制。两税法以资产为宗、夏秋两征，取代租庸调，使朝廷赋税不因户籍逃匿而流失，奠定唐宋以降赋税制度之基，杨炎创议之功不可没。然神策军中尉制以宦官典禁军，本出于奉天之难后天子对武将之深疑，却将废立君王之权交入家奴之手，终唐之世未能拔除。德宗之失，不在志向，而在操之过急、疑之太深：削藩以立威，激成四镇之乱；罪己以收人心，又转而姑息河朔；聚敛以实府库，则驱陆贽于忠州，任裴延龄于度支。陆贽奏议论德宗之病，在于任重而虑轻、功倍而患深。唐室经此二十六年，虽安而元气暗耗，史家论唐之由盛转衰，多自德宗始。",
