    summary: "唐高宗李治（628—683），太宗第九子，母长孙皇后，贞观二十三年（649）六月即位，年二十二。前期有永徽之治：遵贞观遗规，劝课农桑，永徽四年（653）颁《律疏》，即后世《唐律疏议》，为中华法系集大成者。永徽六年（655）废王皇后、立武则天，借势清洗长孙无忌、褚遂良等关陇元老，收揽乾纲。武功极盛：显庆二年（657）苏定方灭西突厥，显庆五年（660）灭百济，总章元年（668）李勣灭高句丽，唐疆域达于鼎盛。晚年患风疾，目不能视，委政武后，中外谓之二圣临朝。弘道元年（683）十二月崩，武后临朝称制，终启武周革命。其一生守成有为而中道失权，上承贞观，下启武周。",
    background: "贞观后期，太宗以辽东之役、宫室营建耗损民力，又以猜忌刑杀驭下：侍中刘洎、刑部尚书张亮皆获罪伏诛，朝局肃杀。储位之争尤剧：太子李承乾与魏王李泰各树党羽，屡起冲突；承乾败废，泰亦见黜。贞观十七年（643），太宗以承乾、泰皆长孙皇后所出，恐立泰则承乾与晋王治皆不自全，遂立十五岁之晋王治为太子，命长孙无忌、褚遂良、李勣等夹辅东宫，自撰《帝范》以训之，犹虑其柔弱，常加忧念。贞观二十三年（649）五月，太宗崩于翠微宫，高宗以二十二岁继统。此时朝堂之上，关陇元老、山东士族、寒门新进并立；宫闱之内，王皇后无子而萧淑妃有宠；西陲则有阿史那贺鲁叛据十姓。永徽之政即在太宗余威、顾命旧臣与内忧外患之中展开，守成与更化、集权与委政两条线索相互纠缠，终贯穿其在位三十四年。",
