          "永徽元年（650）闰五月，敕太尉长孙无忌、司空李勣、左仆射于志宁等删定律令格式，以广视听、一刑罚。永徽三年（652），复诏无忌以下暨律学之士为律作疏，明科条之指归，一断狱之准的；四年（653）十月书成奏上，凡律十二篇五百零二条、疏三十卷，诏颁天下，世称《永徽律疏》，即后世《唐律疏议》。其书以五刑、十恶、八议为纲，列名例、卫禁、职制、户婚、厩库、擅兴、贼盗、斗讼、诈伪、杂律、捕亡、断狱十二篇，疏议释文，一准乎礼，出入人罪皆引律为断，自是治狱者有所准绳，中华法系至此集其大成。",
          "然永徽亦非全然太平。三年（652）十月，睦州青溪县女子陈硕真以妖言聚众，自称文佳皇帝，破睦州、於潜诸县，众至数万；婺州刺史崔义玄率州兵与扬州都督府兵讨平之，余党悉散。与此同时，西突厥阿史那贺鲁于永徽二年（651）叛，击破乙毗射匮可汗，自号沙钵略可汗，寇庭州，杀掠吏民；朝廷遣左武卫大将军梁建方、右骁卫将军契苾何力、葱山道行军总管程知节等屡征之，互有胜负。内忧外患交至，而永徽之治仍得维持，实赖制度修明、用得其人。"
