    interpretation: "肃宗的灵武即位，是在马嵬分兵之后的仓促之举。即位之时，玄宗尚在赴蜀途中，未及册命，严格而论属自立；其后玄宗下诏传位，遣韦见素、房琯奉册宝至灵武，是事后的追认。故肃宗皇位的合法性，终究由平叛事功奠定。此一非常之举虽聚拢抗战士气，也使皇权分裂、父子猜嫌，埋下肃宗朝内争的伏线。肃宗本人有乱世担当，能任郭子仪、李光弼，借回纥之力收复两京；然猜忌功臣，使鱼朝恩监九节度之军，致有相州之败；又倚李辅国典禁兵，使宦官预军成为制度，终唐之世，宦官废立天子、典神策军，其祸实肇于此。收复两京之功与宦官典兵、藩镇坐大之祸并起于肃宗一朝，唐室虽再安，元气已尽，由盛转衰之势遂不可逆。",
