    interpretation: "唐宪宗之治，可一言以蔽：以宦官之兵平藩镇之权，又以宦官之祸终其身。永贞内禅，皇位得于俱文珍等，故即位后虽追慕贞观，而神策军权终不肯外授；元和用兵，仰神策军与内库财赋，天子自将以出，宰相节度皆承其指。其得也，号令出于一人，进退速而成功易；其失也，兵权家奴化，中枢机密归于北司。故元和中兴之中兴，非制度再造，乃皇权、内库、神策军三位一体之临时强干。河朔三镇慑于兵威而受命，其官吏任免、财赋兵额并未尽入朝廷编册，一旦天子暗弱，复叛如故。长庆再失河朔，而天子废立决于家奴，至文宗甘露之变，受制阉竖，唐之国势遂不可复振。论者谓宪宗成也宦官、败也宦官，岂虚言哉。",
