    interpretation: "唐祚倾颓非亡于一日，而成于僖宗一朝，其故有三。其一，黄巢流动作战南北十年，江淮、关中膏腴之地化为焦土，两税法所依之户籍与征收体系彻底瓦解，方镇各留赋税，上供断绝，朝廷财用遂仰诸侯鼻息。其二，广明之役神策军一战溃散，后虽重建，多为宦官典领、市井无赖充数，天子亲军名存实亡，禁廷武力拱手让人。其三，宦官田令孜挟天子以令诸侯，再劫乘舆，威信尽失；朱温、李克用等以镇压黄巢起家，据宣武、河东，秦宗权继乱中原，方镇专命、甲兵自擅之局遂不可返。故僖宗崩后昭宗虽号中兴之主，唐室已无一兵一钱之可用，名存实亡，天祐四年朱温篡唐，水到渠成。",
