          "大中二年（848），沙州人张议潮乘吐蕃内乱，率众起义，逐吐蕃守将，自领沙州刺史。议潮缮甲兵、兴农桑，且耕且战，修缮城堡，训练士卒，结人心而图东向。大中五年（851）七月，议潮遣其兄张议潭奉瓜、沙、伊、肃、鄯、甘、河、西、兰、岷、廓十一州图籍户口归唐，献于阙下。自沙州陷蕃（786）以来，河西沦没近七十年，至是重归唐室版图。宣宗抚纳其降，厚加赏赐，授议潮沙州防御使，旋进归义军节度。",
          "大中五年十一月，宣宗于沙州置归义军，授张议潮归义军节度使、十一州观察使，镇守河西。「归义」之名，即归义大唐之意。张氏世领其职，其后张淮深、张承奉相继，历唐末五代而存。收复河湟，为晚唐最耀眼之边功。然此功非唐廷征伐所得，实赖吐蕃内乱、义军自奋，唐廷不过因势利导，授以节钺、羁縻而已。归义军后来亦渐成河西藩镇，唐之号令能及于瓜沙者亦仅名器，此又为藩镇格局中之一变相。"
