    interpretation: "宣宗之明与唐运之颓，构成晚唐最触目的反差。其人韬晦三十年而得位，黜李德裕、终牛李党争、复河湟、修刑律，个人政治素质不可谓不高；然宦官拥立之制未改，废立之权仍在马元贽、王宗实辈手中，甘露之变以来的痼疾非一明君所能根治。收复河湟声威虽盛，实赖吐蕃内乱与张议潮自奋，唐廷未发大军，所授不过节钺名器，归义军亦渐成河西藩镇。大中之治是晚唐最后一个治世，亦是回光返照：人存政举、人亡政息，宣宗以丹药殒身、储位久悬，交接之际再落宦官之手。懿宗、僖宗荒纵，黄巢乱起，唐祚遂不可复振。故《资治通鉴》以「讫于唐亡，人思咏之」称之，既叹其治，亦悲其势：一人之明，终难挽制度之衰。",
