    interpretation: "《通典》的深层逻辑，在于它回答了一个根本问题：治国应当从何处着手。在杜佑之前，正统观念奉礼乐教化为先务，食货被视为末业。杜佑反其道而行，将食货置于全书之首，以「教化之本在乎足衣食」相号召，等于把经济制度确立为政治的基础。这不是简单的门类次第调整，而是史观的革命：判断一项制度的好坏，先要看它能否使百姓足衣足食、国家财政稳固，其次才是礼乐文饰。第二个贡献，是确立了「通史」的眼光。前代正史各修一朝，制度记载断代为书，难以看出因革。杜佑贯通黄帝至唐天宝，使每一项制度的来龙去脉一目了然，这种会通精神为司马光、郑樵、马端临所继承，构成中国史学的主流传统。第三个贡献，是使典章制度史从纪传体书志中独立出来，成为专门之学；唐以后历朝会要、会典之作，皆沿其流。要理解中国古代国家如何运转，终须回到《通典》所构建的制度框架之中。",
