    interpretation: "节度使制度的兴衰，是唐代军事制度与社会结构剧变的缩影。其设立本为边疆防御之需：疆域扩张、边线延长，临时差遣的元帅无法应对持久战争，固定化、集权化的边防统帅应运而生。但制度一旦与募兵制结合，兵将之间的固定隶属关系使军队私有化，节度使遂成兵将之主。权力重心由关中移至边镇，形成外重内轻。安史之乱并未斩断这一逻辑，反而将节镇模式推广至内地，中央与藩镇、藩镇与藩镇之间形成百年均势：河朔三镇半独立，朝廷以东南八道财赋供养神策军，维系削藩战争。唐后期政治几乎全部围绕节度使问题展开——德宗之愤、宪宗之威、武宗之功，皆系于削藩成败。这一制度最终反噬其创立者，朱温以宣武节度使代唐，开启五代十国之局，至北宋初年方告终结。",
