          "羁縻体系随之崩解。关内道二百九十五府州因河陇陷落而尽失；突厥余部为回纥所并；契丹、奚转附回纥与河北藩镇；东北黑水府州渐没于渤海与契丹；安北、单于二府名存实亡。河北三镇胡化日深，朝廷以羁縻之术待藩镇，节度使父子相袭、贡赋不入，恰是羁縻失控的反噬。西南方向，南诏虽于贞元十年（794）弃吐蕃归唐，实则自擅其兵其民。中央权威一衰，间接统治的脆弱性便暴露无遗。",
          "尽管如此，羁縻府州的制度遗产深远。宋代在西南溪峒地区置羁縻州，元代推行土司制度，明清因之，并设盟旗于蒙古；清雍正朝大规模改土归流，方才逐步以流官取代土官。唐人所创修其教不易其俗、齐其政不易其宜的治理传统，绵延千余年，成为中国古代多民族国家整合边疆的重要路径。唐代八百余府州虽多湮灭于史册，其因俗而治的智慧则历久而弥新。"
