    interpretation: "李商隐的悲剧，表面看是婚姻所致，深层看是晚唐士人依附性生存的必然。唐代进士登第后，仍须由吏部铨选或幕府辟署得官，士人进身往往依附于某位权贵或某党。令狐楚父子于李商隐有知遇栽培之恩，王茂元于其有婚姻之爱，而两方分属牛李两党。李商隐娶王氏女，在牛党看来是背叛，在李党看来又非嫡系；更不幸的是，会昌年间李德裕当政时他正丁母忧，大中年间牛党复起时他又脱不掉李党姻亲的印记，时间上完全错位，两党皆不得其门。其无题诗的朦胧多义，正是这种无法言说的处境在美学上的投射：欲言又止，欲说还休，以密集意象与典故替代直抒胸臆，文本因此具有开放性，千载聚讼而不可穷尽。崔珏「虚负凌云万丈才，一生襟抱未曾开」之叹，既哀其人，也折射出晚唐士人在党争与幕府制度下的普遍命运。",
