    interpretation: "敬宗之弑，非一夫之罪，乃制度之失也。自安史乱后，神策军归于宦官，枢密使典掌机要，天子之禁兵与机密，皆在宦寺之手。元和十五年宪宗见弑，穆宗以宦官立；宝历二年敬宗复见弑，文宗又以宦官立。王守澄一人，预弑宪宗于前，平刘克明、拥文宗于后，再操废立大柄，而朝廷不能加一毫之罚，宰相李逢吉反附之。盖当时之势，宦官操废立之权，宰相持朝议之柄，天子居其间，贤则受制，不肖则速祸。敬宗荒嬉，其死不足惜；然家奴弑君而不能讨，矫诏立君而宰相承命，则唐之纲纪扫地尽矣。故敬宗之弑，实中晚唐宦官专权固化之转折，其后甘露之变，不过其余波耳。",
