    interpretation: "穆宗一朝，史家多讥其昏荒，然其失政之深层，实是元和政策的反动与唐朝结构性矛盾的总爆发。其一，销兵之策以财政逻辑裁撤河朔骄兵，而不知河朔之患不在兵多，在方镇军士的职业化与地域化——一旦失业，即化为叛卒，故三镇之复失，非朱克融、王庭凑之能，乃朝廷自弃其威。其二，穆宗以宦官拥立得位，则神策军中尉、知枢密使之权不可夺，此后敬宗见弑、文宗受制、武宗虽强亦不过权宜，皇权更替竟操于宦官之手。其三，贡举一案开启牛李党争近四十年，士大夫以科场、门荫分阵营，与宦官之祸、藩镇之叛纠缠互因。其四，元和中兴之成功，全系于宪宗之明断与裴度辈之谋略，未尝改革河朔骄兵与宦官典军两大痼疾，故人亡政息，一朝尽毁。穆宗以三十暴崩，特其表征耳。",
