    summary: "唐睿宗李旦（662—716），高宗李治第八子，武后幼子，初名旭轮。文明元年（684）武太后废中宗，立之为帝，政事一决于武后，居别殿，不预朝闻。载初元年（690）武周革命，让位为皇嗣，赐姓武氏，幽居宫中，两妃遇害亦不敢言。唐隆元年（710）六月，其子临淄王李隆基与太平公主诛韦后集团，拥其复位。在位期间太子与公主争权，延和元年（712）八月禅位，以太上皇掌三品以上官除授；先天二年（713）玄宗诛太平公主，始尽归政。开元四年（716）崩，年五十五，葬桥陵，庙号睿宗。两度登极、世称三让天下，是武后专政至开元盛世之间静默的过渡者。",
    background: "唐高宗弘道元年（683）十二月，高宗李治崩，中宗李显即位，武太后临朝称制。中宗欲擢韦后之父韦玄贞为侍中，又欲授乳母之子五品官，与宰相裴炎争执，出以天下与人亦无不可之言。嗣圣元年（684）二月，武太后废中宗为庐陵王，改立豫王李轮为帝，改元文明，是为睿宗。其时武后经营革命已久，改东都为神都，立武氏七庙，朝野已成武氏代唐之势。睿宗生于龙朔二年（662），为武后所生幼子，早年历封殷王、冀王、相王，仪凤三年（678）改名轮。其即位本为武后篡位前之过渡安排，居于别殿，政事一决于武后，不得预闻。载初元年（690）九月，武后称帝，改国号为周，睿宗让位为皇嗣，赐姓武氏。在此格局之下，其一生注定在母亲、侄辈、儿子与姐姐的权力夹缝中求存。",
