          "嗣圣元年（684）二月，中宗欲以韦玄贞为侍中，与裴炎相忤，出狂言以激太后。武后遂废中宗为庐陵王，立豫王轮为帝，改元文明，是为睿宗，年二十二。然帝居别殿，不预朝闻，政事一决于武后；武后追尊武氏先祖为王，立武氏七庙，又改三省六部之名以示革命之兆。其年九月，徐敬业起兵扬州，旋即败亡，裴炎亦以反坐诛。睿宗端拱默处，无一言干政，实为武后代唐之过渡工具。",
