          "帝既复位，当立太子。宋王成器以居长当立，睿宗亦有意之；成器涕泣固让，以为储副天下公器，时平则先嫡长，国难则归有功，韦王隆基有诛韦复唐大功，储位宜归之。群臣亦多言隆基功高，睿宗遂立临淄王隆基为皇太子。然朝权分峙：太平公主自恃定策之功，广置幕府，其时宰相七人，五出其门；太子亦预大政。姑侄各结党羽，竞相倾轧，睿宗居其间，依违不断，欲以两端求平衡。",
          "景云二年（711），侍中宋璟、中书侍郎姚元之密请出公主于蒲州、安置岐王薛王于外州，以清外戚之逼。公主闻之大怒，诉于睿宗，二相同日罢黜。延和元年（712）七月，彗星出西方，入太微，犯南斗。太平公主使术士言于睿宗，谓帝星有变，皇太子当为天子，欲借天象以离间父子。睿宗不为其惑，反以传德避灾为辞，下诏禅位。八月，太子即位，改元先天，尊睿宗为太上皇。然上皇仍自称朕，三品以上官除授及军国大政，皆决于上皇，皇帝但决五品以下而已。"
