          "先天二年（713）七月，太平公主谋废玄宗，窦怀贞、萧至忠、岑羲、崔湜为宰相内应，常元楷、李慈典禁兵，将发难。玄宗与岐王范、薛王业、高力士、王毛仲、姜皎等先发，率兵掩捕，诛其党。公主逃入山寺，赐死于第；窦怀贞自缢，萧至忠、岑羲伏诛，崔湜流赐死。太上皇闻变，登承天门，下诰自今军国政事一取皇帝处分，遂尽归政，徙居百福殿。自延和传位至此，二年之间，朝局始定于一。",
