    interpretation: "睿宗一生，可作弱势君主生存术之注脚。其第一次在位（684—690），名为天子，实居别殿，政事一决于武后，本是武后代唐的过渡工具；其让位，非高风亮节，乃势所必然。武周十五年为皇嗣，两妃被杀而不敢发一言，赖乐工安金藏剖腹鸣冤方免于祸，其忍辱实为宗室在酷吏政治下的唯一活法。唐隆复辟，非其自为，乃子与姊之力；即位之后，太子与太平公主各据半朝，七相五出公主之门，睿宗居中调停，依违两可，实则以平衡求自保。延和禅位，太平公主本以星象离间，反促其决意传位，可见其让之一贯。先天政变之后归政，终于全身而退。史臣或称其谦恭孝友，或讥其居位无政事；平心论之，睿宗无开创之才，有知退之明，在武后专政至开元盛世之间，以静默承上启下，其让实为保全家族与自身之策，亦为李唐国祚得以延续之一因。",
