          "武三思既结韦后，视五王为仇雠。神龙二年（706），三思使人上疏，告五王与王同皎谋反，帝信之，贬张柬之为新州司马、崔玄暐为白州司马、敬晖为崖州司马、桓彦范为泷州司马、袁恕己为窦州司马，寻皆使人追杀之，天下冤之。三思既去五王，权倾人主，常曰：「我不知世间何者谓之善人、何者谓之恶人，但于我善者即为善，恶我者即为恶。」朝士出其门者，不数年多至卿相，韦武并势，莫能谁何。",
