          "太子李重俊非韦后所生，韦后、安乐公主数加凌辱，安乐公主竟欲废太子而立己为太女。景龙元年（707）七月，重俊不堪其迫，与左羽林大将军李多祚、将军李思冲、李承况、独孤祎之等矫制发左右羽林兵三百余人，先诛武三思、武崇训父子于其第，遂引兵攻玄武门，声言诛韦后、安乐公主与上官婉儿。宫门闭，中宗登玄武门楼，兵溃，重俊奔终南山，为左右所杀，传首长安，枭于太庙，党从多夷灭。",
          "景龙之变后，韦氏益无忌惮。宗楚客累迁至中书令，附韦后图「圣武」之运，劝后袭武后故事；景龙三年（709），有言天降祥瑞当应皇后临朝者，中宗虽诛其言者，而韦党之盛转不可制。其时墨敕斜封之官满阙庭，纲纪大坏，侍中魏知古、黄门侍郎宋璟等屡谏不听。中宗又数与韦后微服出游，观灯于市里，出幸其女长宁公主、安乐公主及群臣第宅，游宴无节，朝政丛脞，中外积怨。",
          "景龙四年（710）六月，中宗暴崩于神龙殿，年五十五。《旧唐书》《新唐书》皆载韦后与安乐公主进毒饼，一说散骑常侍马秦客、光禄少卿杨均所为；然《通鉴考异》已疑其事，近世学者亦多以为中宗或以疾崩，弑君之说乃唐隆政变后诬辞，今两存之。韦后秘不发丧，立温王李重茂为皇太子，甲子即位，韦后临朝称制。未几，临淄王李隆基与太平公主举唐隆之变，诛韦后、安乐公主，迎睿宗李旦复位，中宗葬于定陵，谥曰孝和皇帝。"
