    interpretation: "中宗一生，是武周革命与李唐复国之间的过渡。其庸懦非特禀性，亦是十四年幽废磨折所致：房州岁月使其既畏武氏之余威，又负韦氏患难之诺，复位之后，惟知纵妻女以偿旧约，不复有君主之断。神龙政变虽复唐号，却未清武氏之根，五王拥立有功而旋遭贬杀，敬晖等束手待毙，说明复辟实为武韦势力的换位，而非李唐皇权的重建。自神龙至唐隆，四年之间中宗、殇帝、睿宗三易其主，皆出于后妃宗女之手，可见武后所开「女主临朝」之风至是犹未殄。其宽纵所酿之祸，终赖其侄李隆基与妹太平公主以唐隆政变收场，也为后来的开元之治扫清了道路。",
